/* Bloco padrão de foto e anexo de documento (padrão da Nova Transferência, Rodrigo 26/11/2026): GRUPO com o título acima, quadro com a linha "Tipo do documento" (seleção à direita) e UMA linha "Anexos" que abre o painel com as origens (Usar câmera, Selecionar arquivo); a ajuda e o estado ficam abaixo do quadro, em letra pequena. A tela só escuta o evento 'doc-capture'
   (detail: file, source, side, block). Nos blocos com frenteVerso, "Usar câmera" tira duas fotos seguidas: depois da frente o mesmo botão pede o verso (side: frente, verso, unica). */
(function(root){
'use strict';
const ICON={camera:'M4 8h3l2-3h6l2 3h3v11H4zM12 17a4 4 0 1 0 0-8 4 4 0 0 0 0 8z',file:'M6 3h8l4 4v14H6zM14 3v4h4M9 12h6M9 16h6'};
const ACCEPT='image/jpeg,image/png,image/webp,application/pdf';
const svg=d=>'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="'+d+'"/></svg>';
const LABEL={camera:'Usar câmera',file:'Selecionar arquivo'};
const SETA='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 6 6 6-6 6"/></svg>';
const opHtml=kind=>'<button type="button" class="transferencia-linha transferencia-linha-acao transferencia-folha-op" data-doc-pick="'+kind+'"><span class="transferencia-linha-rotulo">'+LABEL[kind]+'</span><span class="transferencia-circulo" aria-hidden="true">'+svg(ICON[kind])+'</span></button>';
function markup(title,help,opts={}){const tipos=opts.tipos?'<label class="doc-capture-type">Tipo do documento<select aria-label="Tipo do documento">'+opts.tipos.map(t=>'<option>'+t+'</option>').join('')+'</select></label>':'';
 return '<div class="doc-capture"'+(opts.frenteVerso?' data-doc-sides':'')+'><strong class="doc-capture-titulo">'+title+'</strong><div class="doc-capture-quadro">'+tipos+'<div class="doc-capture-anexos transferencia-tela"><button type="button" class="transferencia-linha transferencia-linha-acao doc-capture-abre"><span class="transferencia-linha-rotulo">Anexos</span><span class="transferencia-linha-valor">Nenhum</span><span class="transferencia-seta" aria-hidden="true">'+SETA+'</span></button><div class="doc-capture-painel transferencia-tela compras-escolha-painel compras-aniv-painel compras-data-painel transferencia-anexos-painel" hidden><p class="transferencia-folha-titulo">Anexar documento</p><div class="transferencia-quadro">'+opHtml('camera')+opHtml('file')+'<button type="button" class="transferencia-linha transferencia-linha-acao transferencia-folha-op doc-capture-skip" hidden><span class="transferencia-linha-rotulo">Só a frente</span></button></div></div></div></div><p class="doc-capture-ajuda">'+help+'</p><p class="doc-capture-status" role="status"></p></div>'}
function create(title,help,opts){const t=document.createElement('template');t.innerHTML=markup(title,help,opts);return t.content.firstElementChild}
/* Texto da linha de estado e liga/desliga os dois botões. */
function estado(block,{texto,ativo=true}={}){const s=block.querySelector('.doc-capture-status');if(s&&texto!==undefined)s.textContent=texto+(block.dataset.docNext==='verso'&&!/verso/.test(texto)?' Agora o verso do documento.':'');block.querySelectorAll('[data-doc-pick], .doc-capture-abre').forEach(b=>{b.disabled=!ativo});if(!ativo&&block._abrir)block._abrir(false)}
const tipo=block=>block.querySelector('.doc-capture-type select')?.value||'';
/* Volta o bloco ao estado normal (sem verso pendente). */
const rotulo=b=>b.querySelector('.transferencia-linha-rotulo')||b;
function zerarLado(block){delete block.dataset.docNext;const cam=block.querySelector('[data-doc-pick=camera]');if(cam)rotulo(cam).textContent=LABEL.camera;const skip=block.querySelector('.doc-capture-skip');if(skip)skip.hidden=true}
function pedirVerso(block){block.dataset.docNext='verso';rotulo(block.querySelector('[data-doc-pick=camera]')).textContent='Tirar foto do verso';block.querySelector('.doc-capture-skip').hidden=false;estado(block,{texto:'Frente enviada. Agora o verso do documento.'})}
document.addEventListener('change',e=>{const t=e.target;if(t.matches&&t.matches('.doc-capture-type select'))zerarLado(t.closest('.doc-capture'))});
/* Linha Anexos: abre o painel flutuante (o mesmo da Nova Transferência); escolher uma origem ou "Só a frente" fecha. */
function abrirPainel(block){const U=window.CicluzComprasUI,abre=block.querySelector('.doc-capture-abre'),painel=block.querySelector('.doc-capture-painel');if(!abre||!painel)return;if(!block._abrir){if(U&&U.flutuante)block._abrir=U.flutuante(abre,painel);else block._abrir=sim=>{painel.hidden=!sim}}block._abrir(painel.hidden)}
document.addEventListener('click',e=>{const ab=e.target.closest('.doc-capture-abre');if(ab){if(!ab.disabled)abrirPainel(ab.closest('.doc-capture'));return}const skip=e.target.closest('.doc-capture-skip');if(skip){const bl=skip.closest('.doc-capture');if(bl._abrir)bl._abrir(false);zerarLado(bl);estado(bl,{texto:'Só a frente foi enviada.'});return}const b=e.target.closest('.doc-capture [data-doc-pick]');if(!b||b.disabled)return;const block=b.closest('.doc-capture');if(block._abrir)block._abrir(false);const source=b.dataset.docPick,input=document.createElement('input');input.type='file';input.accept=source==='camera'?'image/*':ACCEPT;if(source==='camera')input.setAttribute('capture','environment');
 input.onchange=()=>{const file=input.files&&input.files[0];if(!file)return;const duplo=source==='camera'&&block.hasAttribute('data-doc-sides'),side=!duplo?'unica':block.dataset.docNext==='verso'?'verso':'frente';
  if(side!=='frente')zerarLado(block);const val=block.querySelector('.doc-capture-abre .transferencia-linha-valor');if(val)val.textContent=side==='verso'?'Frente e verso':'1 arquivo';block.dispatchEvent(new CustomEvent('doc-capture',{bubbles:true,detail:{file,source,side,block}}));if(side==='frente')pedirVerso(block)};input.click()});
root.CicluzDocCapture={markup,create,estado,tipo,ICON};
})(window);
